import {inspectSharedMapInputs,HOST_INPUT_LIMITS,freezeInput,qualifyInputOwner} from './shared-map-admission.js';
import {sharedMapInputInventory,prepareSharedMapProjections} from './shared-map-inputs.js';
import {originalMaterialComponents} from '../simulation/original-support-ports.js';
import {bounds,segmentTriangle,dot,sub,EPS} from '../../workbenches/furnished-house/geometry.js';

const used=new WeakSet(),vector=p=>Array.isArray(p)&&p.length===3&&p.every(Number.isFinite);
const pendingCodes=new Set(['SURFACE_PLAN_UNBOUND','ORDINARY_ALTERNATIVES_NOT_READY','ORDINARY_BINDINGS_NOT_READY','BIRTH_DERIVATION_PLAN_UNBOUND']);
const unprovedCodes=new Set(['CONTACT_PROOF_NOT_REVIEWED','SOURCE_BOND_WITNESS_NOT_APPROVED','SOURCE_ENDPOINT_UNBOUND']);
export class SourcePreparationBoundary extends Error{constructor(code,detail){super(code+': '+detail);this.name='SourcePreparationBoundary';this.code=code;}}

// Metadata only. Known pending saddle proofs are explicitly named by the caller;
// unknown identities, quantities, ranges, modes or source witnesses cannot pass.
export function preflightSharedMapSourcePreparation({descriptor,policy,inventory,budget,pendingBondIds=[]}){
  const admission=inspectSharedMapInputs(descriptor,inventory,policy),p=admission.plan,pending=new Set(pendingBondIds),problems=admission.findings.filter(f=>!pendingCodes.has(f.code)&&!(unprovedCodes.has(f.code)&&[...pending].some(id=>f.id===id||f.id===id+'/parent'||f.id===id+'/child')));
  const counts={owners:p.owners.length,parts:p.parts.length,physicalTriangles:p.parts.reduce((n,p)=>n+p.physicalTriangles,0)},knownShapes=HOST_INPUT_LIMITS.shapes-HOST_INPUT_LIMITS.fallbackShapes,knownTriangles=HOST_INPUT_LIMITS.triangles-HOST_INPUT_LIMITS.fallbackTriangles;
  if(!budget||!['owners','parts','physicalTriangles'].every(k=>Number.isSafeInteger(budget[k])&&budget[k]>0)||counts.owners>budget.owners||counts.parts>budget.parts||counts.physicalTriangles>budget.physicalTriangles||counts.parts>knownShapes||counts.physicalTriangles>knownTriangles||!Object.values(counts).every(Number.isSafeInteger))problems.push({code:'SOURCE_PREPARATION_BUDGET',id:p.placeId,detail:counts});
  if(!p.owners.length||p.owners.length!==p.parts.length||p.owners.some(o=>o.parts.length!==1)||p.parts.some(p=>!Number.isSafeInteger(p.physicalTriangles)||p.physicalTriangles<1))problems.push({code:'SOURCE_PREPARATION_COHORT',id:p.placeId,detail:'One complete physical part per selected canonical owner is required for this bounded phase.'});
  return freezeInput({version:1,status:problems.length?'NOT_READY':'PREFLIGHT_READY',phase:'SOURCE_PREPARATION_PREFLIGHT',counts,problems,pendingBondIds:[...pending],limits:HOST_INPUT_LIMITS,geometryFit:'Originals fit; derived arrays must acquire the same bounded registry reserve before use.',admission});
}

export function sourceSurfaceSpan(surface,grid){const b=bounds(surface.triangles.flat()),min=b.min.map((v,i)=>Math.floor((v-grid.origin[i])/grid.pitch[i]+EPS)),max=b.max.map((v,i)=>v-b.min[i]<EPS?min[i]:Math.ceil((v-grid.origin[i])/grid.pitch[i]-EPS)-1);return {min,max};}

// Map ONE already fixed original face. No contact search, nearest-face choice,
// common selector, cell clamping, native record inference or support evaluation.
export function deriveSharedSourceEndpoint({endpoint,part,components,surfaces,grid}){
  const e=endpoint,t=part.triangles[e.primitive],component=components.find(c=>c.primitives.includes(e.primitive));
  if(component?.id!==e.component||!t||!vector(e.point)||segmentTriangle(e.point,e.point,t)===null)throw new SourcePreparationBoundary('ORIGINAL_WITNESS_NOT_REPRESENTED',e.partId);
  if(e.selector&&(!vector(e.selector.min)||!vector(e.selector.max)||e.point.some((v,i)=>v<e.selector.min[i]-EPS||v>e.selector.max[i]+EPS)))throw new SourcePreparationBoundary('ORIGINAL_SELECTOR_NOT_REPRESENTED',e.partId);
  let candidates=surfaces.filter(s=>s.nativePartId===e.partId&&s.triangles.includes(t)),surfacePoint=[...e.point],channel='surface';
  if(!candidates.length){
    candidates=surfaces.filter(s=>s.nativePartId===e.partId&&s.id.endsWith('/plane')&&s.thickness>0&&!s.solidTriangles?.length).filter(s=>{const d=dot(sub(e.point,s.triangles[0][0]),s.normal),lo=s.kind==='floor'?-s.thickness:-s.thickness/2,hi=s.kind==='floor'?0:s.thickness/2;return d>=lo-EPS&&d<=hi+EPS;});
    if(candidates.length===1){const s=candidates[0],d=dot(sub(e.point,s.triangles[0][0]),s.normal);surfacePoint=e.point.map((v,i)=>v-d*s.normal[i]);channel='solid';}
  }
  if(candidates.length!==1||!candidates[0].triangles.some(t=>segmentTriangle(surfacePoint,surfacePoint,t)!==null))throw new SourcePreparationBoundary('SOURCE_PROJECTION_NOT_UNIQUE',e.partId);
  const s=candidates[0],span=sourceSurfaceSpan(s,grid),cell=surfacePoint.map((v,i)=>Math.floor((v-grid.origin[i])/grid.pitch[i]+EPS));
  if(cell.some((v,i)=>v<span.min[i]||v>span.max[i]))throw new SourcePreparationBoundary('SOURCE_CELL_OUTSIDE_ORIGINAL_LOOP',e.partId);
  const suffix=s.id.slice(s.id.lastIndexOf('/part/')+6).split('/').slice(1).join('/');
  return {status:'DERIVED_SOURCE_PLAN_UNREVIEWED',sourceSurfaceId:s.id,sourceSpan:span,originalPrimitive:e.primitive,originalComponent:e.component,bindingPlan:{kind:'source-blueprint-original-face-v1',channel,suffix,surfacePoint,cell,nativeRecordId:null,nativeCellId:null,proofRef:null},nativeAuthority:'UNBORN_UNPROVED'};
}

// Reuse the host's one decoded model/source owner and one registry. This source
// phase is explicit, single-use, and never calls the hybrid producer or trial.
export async function prepareSharedMapSourceInputs({compiled,descriptor,policy,budget,pendingBondIds=[],loadProjection,signal,onWorldTable=()=>{},onBlueprints=()=>{}}){
  if(used.has(compiled)||compiled.sources.metrics().transformedQueries||compiled.sources.metrics().nativeSourceExpansions)throw new SourcePreparationBoundary('SOURCE_OWNER_ALREADY_USED','A second preparation/transform is not permitted');
  const inventory=sharedMapInputInventory(compiled.model),preflight=preflightSharedMapSourcePreparation({descriptor,policy,inventory,budget,pendingBondIds});
  if(preflight.status!=='PREFLIGHT_READY')throw new SourcePreparationBoundary('SOURCE_PREFLIGHT_NOT_READY',JSON.stringify(preflight.problems));
  used.add(compiled);
  const p=preflight.admission.plan,pins=[],originals=new Map(),components=new Map(),bundles=new Map(),findings=[];let query,releaseProvider,worldTable,blueprints;
  const live=()=>signal?.throwIfAborted(),qualify=id=>qualifyInputOwner(p.placeId,id),before=compiled.sources.metrics();
  try{
    await prepareSharedMapProjections({model:compiled.model,sources:compiled.sources,projections:p.projections,loadProjection,signal});live();query=compiled.createQuerySource();
    for(const spec of p.parts){live();const pin=query.pinOriginal(spec.id);pins.push(pin);if(pin.shape.triangles.length!==spec.physicalTriangles)throw new SourcePreparationBoundary('ORIGINAL_COUNT_CHANGED',spec.id);originals.set(spec.id,pin.shape);components.set(spec.id,originalMaterialComponents(pin.shape.triangles));}
    worldTable={version:1,sourceRevision:p.sourceRevision,frame:'emitted-world',grid:p.grid,parts:p.parts.map(spec=>({id:spec.id,ownerId:spec.ownerId,globalIndex:spec.globalIndex,geometry:spec.geometry,physicalGeometry:compiled.model.partById.get(spec.id).physicalGeometry??spec.geometry,matrix:compiled.model.partById.get(spec.id).matrix,closed:originals.get(spec.id).closed,triangles:originals.get(spec.id).triangles,components:components.get(spec.id)}))};
    await onWorldTable(worldTable);live();
    releaseProvider=compiled.sources.useOriginalShapes(id=>{const original=originals.get(id);if(!original)throw new SourcePreparationBoundary('OUTSIDE_PREPARATION_COHORT',id);return original;});
    const ownerRows=[];
    for(const owner of p.owners){live();const b=compiled.sources.sourcesForCarrier(owner.id);if(b.openings.length)throw new SourcePreparationBoundary('MOVING_SOURCE_NOT_ADMITTED',owner.id);bundles.set(owner.id,b);
      for(const s of b.surfaces){pins.push(query.reserveSourceGeometry('preparation/'+s.id,s.triangles));if(s.solidTriangles&&s.solidTriangles!==s.triangles)pins.push(query.reserveSourceGeometry('preparation-solid/'+s.id,s.solidTriangles));}
      const fuelAssigned=b.surfaces.reduce((n,s)=>n+s.fuelAmount,0),finishAssigned=b.surfaces.reduce((n,s)=>n+(s.finish?.amount??0),0),allowance=64*Number.EPSILON*Math.max(1,owner.fuelAmount+(owner.finish?.amount??0))*b.surfaces.length;
      if(Math.abs(fuelAssigned-owner.fuelAmount)>allowance||Math.abs(finishAssigned-(owner.finish?.amount??0))>allowance)throw new SourcePreparationBoundary('CANONICAL_ALLOCATION_CHANGED',owner.id);
      ownerRows.push({id:owner.id,mode:owner.mode,canonicalFuelAmount:owner.fuelAmount,fuelClass:owner.fuelClass,canonicalFinish:owner.finish,fuelAssigned,finishAssigned,arithmeticAllowance:allowance,surfaces:b.surfaces.map(s=>({id:s.id,nativePartId:s.nativePartId,kind:s.kind,normal:s.normal,thickness:s.thickness,triangles:s.triangles.length,fuelAmount:s.fuelAmount,fuelClass:s.fuelClass,finish:s.finish??null,span:sourceSurfaceSpan(s,p.grid)}))});
    }
    blueprints={version:1,sourceRevision:p.sourceRevision,surfaces:[...bundles.values()].flatMap(b=>b.surfaces),openings:[]};await onBlueprints(blueprints);live();
    const derived=structuredClone(p);for(const part of derived.parts){const ss=bundles.get(part.ownerId).surfaces.filter(s=>s.nativePartId===part.id);part.surfacePlan={kind:'existing-blueprint-v1',allocation:'full-canonical-owner',definitions:ss.length,triangles:ss.reduce((n,s)=>n+s.triangles.length,0),proofRef:null};}
    const endpoints=[];
    for(const b of derived.support.bonds){if(pendingBondIds.includes(b.id)){findings.push({code:'PENDING_INDEPENDENT_SOURCE_PROOF',id:b.id});continue;}for(const side of ['parent','child']){const e=b[side];try{const mapping=deriveSharedSourceEndpoint({endpoint:e,part:{triangles:originals.get(e.partId).triangles},components:components.get(e.partId),surfaces:bundles.get(qualify(compiled.model.partById.get(e.partId).carrierId)).surfaces,grid:p.grid});e.bindingPlan=mapping.bindingPlan;endpoints.push({bondId:b.id,side,originalWitness:structuredClone(p.support.bonds.find(v=>v.id===b.id)[side]),...mapping});}catch(error){if(!(error instanceof SourcePreparationBoundary))throw error;findings.push({code:error.code,id:b.id+'/'+side,detail:error.message});endpoints.push({bondId:b.id,side,status:'UNBOUND',originalWitness:structuredClone(e),reason:error.code});}}}
    const ownerSet=new Set(p.owners.map(o=>o.id)),alternatives=p.support.ordinaryAlternatives.map(row=>({ownerId:row.ownerId,semantics:row.semantics,parents:row.parentIds.map(parentId=>({parentId,inCohort:ownerSet.has(parentId),status:ownerSet.has(parentId)?'IN_COHORT_NATIVE_ALTERNATIVE_UNPROVED':'OUTSIDE_SELECTED_COHORT_UNRESOLVED'}))}));
    const after=compiled.sources.metrics();if(after.transformedQueries-before.transformedQueries!==p.parts.length||after.nativePartTransforms||after.renderExpansions||after.presentationPartTransforms)throw new SourcePreparationBoundary('SOURCE_TRANSFORM_BUDGET','Every selected original must transform exactly once');
    return {version:1,status:'NOT_READY',phase:'SOURCE_MAPPING_PROPOSAL',preflight:{counts:preflight.counts,limits:preflight.limits},owners:ownerRows,endpoints,findings,ordinaryAlternatives:alternatives,originalRootBoundaries:p.context?.reviewedSourceRoots?.alternativeBoundaries??[],proposedDescriptor:derived,admission:inspectSharedMapInputs(derived,inventory,policy),resources:{geometry:after,query:query.metrics(),originalParts:p.parts.length,originalTriangles:worldTable.parts.reduce((n,p)=>n+p.triangles.length,0),blueprintSurfaces:blueprints.surfaces.length,blueprintTriangles:blueprints.surfaces.reduce((n,s)=>n+s.triangles.length,0),nativeCompiles:0,producers:0,trials:0,supportEvaluations:0,clockSteps:0,renderers:0,builds:0}};
  }catch(error){if(!error.preparation)error.preparation={code:error.code??(/combined.*cache|source.*cache/i.test(error.message)?'SOURCE_PREPARATION_CACHE_LIMIT':'SOURCE_PREPARATION_FAILED'),detail:error.message,worldTableProduced:!!worldTable,geometry:compiled.sources.metrics(),query:query?.metrics()};throw error;}
  finally{releaseProvider?.();for(const pin of pins)pin.release();query?.dispose();}
}

import {inspectSharedMapInputs,MapInputNotReadyError,qualifyInputOwner,freezeInput,sameInput} from './shared-map-admission.js';
import {createRegionalSourcePilot} from '../simulation/regional-source-pilot.js';
import {createOriginalSupportPorts,originalMaterialComponents} from '../simulation/original-support-ports.js';
import {materialTransmission} from '../../workbenches/furnished-house/scene.js';
import {bounds,clipTriangle,triangleArea,segmentTriangle,EPS} from '../../workbenches/furnished-house/geometry.js';

// This inventory reads identities/counts, never transforms source positions.
export function sharedMapInputInventory(model){
  return {placeId:model.placeId,partCount:model.parts.length,ownerCount:model.carriers.length,geometryIds:Object.keys(model.library.geometries),
    owners:model.carriers.map((o,i)=>({id:o.id,globalIndex:i,parts:o.parts.map(n=>model.parts[n]).filter(p=>p.physical).map(p=>p.id),supports:o.supports,fuelAmount:o.fuelAmount,fuelClass:o.fuelClass,finish:o.finish??null})),
    parts:model.parts.flatMap((p,globalIndex)=>{if(!p.physical)return [];const g=model.library.geometries[p.physicalGeometry||p.geometry];return [{id:p.id,ownerId:p.carrierId,globalIndex,geometry:p.geometry,physicalTriangles:(g.index?.array.length??g.attributes.position.array.length/3)/3,bounds:p.bounds,static:!p.portalId&&!p.openMatrix,sourceRange:p.originalRange??null}];})};
}

export async function loadMapInputJSON(resource,signal){
  const url=new URL('../../'+resource.path,import.meta.url);signal?.throwIfAborted();const response=await fetch(url,{signal});if(!response.ok)throw Error('Map input HTTP '+response.status);
  const bytes=new Uint8Array(await response.arrayBuffer()),digest=await crypto.subtle.digest('SHA-256',bytes),hash=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');
  if(hash!==resource.sha256)throw Error('Map input pin mismatch: '+resource.path);signal?.throwIfAborted();return JSON.parse(new TextDecoder().decode(bytes));
}

function checkProjection(projection,physical,render,mapping){
  for(const [raw,expected]of [[physical,projection.physical],[render,projection.render]]){
    const a=raw?.attributes?.position;if(a?.type!=='Float32Array'||a.itemSize!==3||a.array.length!==expected.vertices*3||a.array.some(n=>!Number.isFinite(n)||Math.fround(n)!==n)||(raw.index?.array.length??a.array.length/3)!==expected.triangles*3)throw Error('Final Float32 projection identity/count changed');
  }
  const physicalIndices=physical.index?.array??Array.from({length:projection.physical.vertices},(_,i)=>i),renderIndices=render.index?.array??Array.from({length:projection.render.vertices},(_,i)=>i),map=mapping.renderToPhysicalVertex;
  if(!Array.isArray(map)||map.length!==projection.render.vertices||renderIndices.length!==physicalIndices.length)throw Error('Projection mapping incomplete');
  for(let i=0;i<renderIndices.length;i++){
    const r=renderIndices[i],p=physicalIndices[i];if(!Number.isSafeInteger(r)||r<0||r>=projection.render.vertices||!Number.isSafeInteger(p)||p<0||p>=projection.physical.vertices||map[r]!==p)throw Error('Projection primitive/vertex lineage changed');
    for(let k=0;k<3;k++)if(!Object.is(render.attributes.position.array[r*3+k],physical.attributes.position.array[p*3+k]))throw Error('Render vertex differs from final physical Float32 buffer');
  }
}

// Shared by the disabled host factory and the separately authorized source-only
// preparation phase. Its caller must first admit the exact projection metadata.
export async function prepareSharedMapProjections({model,sources,projections,loadProjection=loadMapInputJSON,signal,assertLive=()=>signal?.throwIfAborted()}){
  assertLive();const loaded=[];
  for(const p of projections){const buffers=await Promise.all([p.physical,p.render,p.mapping].map(ref=>loadProjection(ref,signal)));assertLive();checkProjection(p,...buffers);loaded.push({p,buffers});}
  assertLive();
  // No mutation until every pinned resource/mapping and abort check passes.
  model.library={...model.library,geometries:{...model.library.geometries}};
  for(const {p,buffers:[physical,render]}of loaded){
    if(model.parts.length!==p.part.globalIndex||model.carriers.length!==p.owner.globalIndex)throw Error('Projection append revision changed');
    const owner={...structuredClone(p.owner),id:qualifyInputOwner(model.placeId,p.owner.id),parts:[p.part.globalIndex],supports:[],adjacency:[],supportEvidence:[],attachments:[],anchors:[]},part={...structuredClone(p.part),carrier:p.owner.globalIndex,carrierId:owner.id,material:owner.material,physical:true};
    model.library.geometries[part.physicalGeometry]=physical;model.library.geometries[part.geometry]=render;model.carriers.push(owner);model.carrierById.set(owner.id,owner);model.parts.push(part);model.partById.set(part.id,part);sources.registerProjectionCarrier(owner.id);
  }
}

// Factory is explicit and reusable. No destination/menu calls it by default.
// Its single owned session is attached AFTER the host decode/source owner.
export function createSharedMapInputFactory({descriptor,policy,loadProjection=loadMapInputJSON}){
  const captured=freezeInput(structuredClone(descriptor)),capturedPolicy=freezeInput(structuredClone(policy));
  return ({model,sources,signal})=>{
    const report=inspectSharedMapInputs(captured,sharedMapInputInventory(model),capturedPolicy);let prepared=false,closed=false,binding=null,preparing=null,binds=0,lastProducer=null;
    const live=()=>{if(closed)throw Error('Map input session disposed');signal?.throwIfAborted();};
    const ready=()=>{live();if(report.status!=='READY')throw new MapInputNotReadyError(report);};
    const plan=report.plan,qualify=id=>qualifyInputOwner(model.placeId,id),ownerModes=Object.freeze(Object.fromEntries(report.status==='READY'?plan.owners.map(o=>[o.id,o.mode]):[]));
    async function prepare(){
      ready();if(prepared)return;if(preparing)return preparing;
      preparing=prepareSharedMapProjections({model,sources,projections:plan.projections,loadProjection,signal,assertLive:live}).then(()=>{prepared=true;});try{await preparing;}finally{preparing=null;}
    }
    function bindRegistry(registry){
      ready();if(!prepared)throw Error('Prepare map inputs before creating the world');if(binding)throw Error('Previous map input binding must be disposed before reset');
      const pins=[],originals=new Map(),components=new Map(),bundles=new Map();let releaseProvider,producer,disposed=false;
      const dispose=()=>{if(disposed)return;disposed=true;producer?.dispose();if(producer)lastProducer=producer.diagnostics();releaseProvider?.();for(const p of pins)p.release();pins.length=0;originals.clear();components.clear();bundles.clear();binding=null;};
      try{
        for(const p of plan.parts){const pin=registry.pinOriginal(p.id);pins.push(pin);if(pin.shape.triangles.length!==p.physicalTriangles)throw Error('Original source triangle count changed');originals.set(p.id,pin.shape);components.set(p.id,originalMaterialComponents(pin.shape.triangles));}
        releaseProvider=sources.useOriginalShapes(id=>{const shape=originals.get(id);if(!shape)throw Error('Out-of-cohort original source: '+id);return shape;});
        for(const o of plan.owners){const b=sources.sourcesForCarrier(o.id);bundles.set(o.id,b);for(const p of plan.parts.filter(p=>p.ownerId===o.id)){
          const ss=b.surfaces.filter(s=>s.nativePartId===p.id);if(ss.length!==p.surfacePlan.definitions||ss.reduce((n,s)=>n+s.triangles.length,0)!==p.surfacePlan.triangles)throw Error('Source blueprint derivation differs from admitted plan');
        }for(const s of b.surfaces){pins.push(registry.reserveSourceGeometry('input/'+s.id,s.triangles));if(s.solidTriangles&&s.solidTriangles!==s.triangles)pins.push(registry.reserveSourceGeometry('input-solid/'+s.id,s.solidTriangles));}}
        const endpoint=(e,kind)=>{
          const part=model.partById.get(e.partId),ts=originals.get(e.partId).triangles,bp=e.bindingPlan,s=bundles.get(part.carrierId).surfaces.find(s=>s.id===part.carrierId+'/part/'+model.parts.indexOf(part)+'/'+bp.suffix),component=components.get(e.partId).find(c=>c.primitives.includes(e.primitive));
          if(component?.id!==e.component||kind!=='fixed-embed'&&segmentTriangle(e.point,e.point,ts[e.primitive])===null||!s)throw Error('Original endpoint component/primitive/surface differs from reviewed plan');
          const sourcePoint=bp.surfacePoint,box=bounds(s.triangles.flat()),lo=box.min.map((v,i)=>Math.floor(v/plan.grid.pitch[i]+EPS)),hi=box.max.map((v,i)=>v-box.min[i]<EPS?lo[i]:Math.ceil(v/plan.grid.pitch[i]-EPS)-1),cell=sourcePoint.map((v,i)=>Math.floor(v/plan.grid.pitch[i]+EPS));
          if(!sameInput(cell,bp.cell)||cell.some((v,i)=>v<lo[i]||v>hi[i])||!s.triangles.some(t=>segmentTriangle(sourcePoint,sourcePoint,t)!==null))throw Error('Own source projection/cell differs from reviewed plan');
          if(bp.channel==='surface'&&!sameInput(sourcePoint,e.point))throw Error('Surface endpoint requires its own source-face point');
          if(bp.channel==='solid'&&!s.triangles.some(t=>segmentTriangle(e.point,e.point,t)!==null)){
            // Existing nativePanel projects a measured original solid to its
            // authored thermal plane. Validate this reviewed projection, then
            // leave actual clipped solid/record authority to genuine birth.
            if(!s.id.endsWith('/plane')||!(s.thickness>0)||s.solidTriangles?.length)throw Error('Solid projection derivation is not ready for this source');
            const offset=e.point.reduce((n,v,i)=>n+(v-sourcePoint[i])*s.normal[i],0),projected=e.point.map((v,i)=>v-offset*s.normal[i]),low=s.kind==='floor'?-s.thickness:-s.thickness/2,high=s.kind==='floor'?0:s.thickness/2;
            if(offset<low-EPS||offset>high+EPS||Math.hypot(...projected.map((v,i)=>v-sourcePoint[i]))>EPS)throw Error('Solid projection differs from measured original native panel');
          }
          const clip={min:cell.map((v,i)=>v*plan.grid.pitch[i]-EPS),max:cell.map((v,i)=>(v+1)*plan.grid.pitch[i]+EPS)};
          if(s.triangles.flatMap(t=>clipTriangle(t,clip)).reduce((n,t)=>n+triangleArea(t),0)<EPS)throw Error('Source endpoint has no positive thermal patch');
          return {partId:e.partId,point:[...e.point],primitives:[e.primitive],sourceSurfaceId:s.id,cell,nativeRecordId:null};
        };
        const support={parts:plan.parts.map(p=>({id:p.id,ownerId:p.ownerId})),bonds:plan.support.bonds.map(b=>({id:b.id,kind:b.kind,direction:b.direction,sourceSha256:b.proofRef.sha256,parent:endpoint(b.parent,b.kind),child:endpoint(b.child,b.kind)})),anchors:plan.support.anchors.map(({partId,elevation,component})=>({partId,elevation,component})),requirements:plan.support.requirements.map(g=>({id:g.id,ownerId:qualify(g.ownerId),portIds:g.portIds,upperBondId:g.upperBondId})),approvedMounts:[]};
        for(const b of support.bonds)if(b.kind==='fixed-assembly-mount')support.approvedMounts.push(structuredClone(b));
        const core=createOriginalSupportPorts({...support,parts:support.parts.map(p=>({...p,triangles:originals.get(p.id).triangles}))});try{for(const b of core.bindings())for(const side of ['parent','child']){const spec=plan.support.bonds.find(v=>v.id===b.id)[side];if(b[side].component!==spec.component||b[side].primitive!==spec.primitive)throw Error('Original endpoint retarget forbidden');}}finally{core.dispose();}
        const regionalOwners=plan.owners.filter(o=>ownerModes[o.id]==='regional'),allowedOwnerIds=new Set(plan.owners.map(o=>o.id));
